use crate::geom::Pt;
#[derive(Clone, Copy)]
pub struct Node { pub i: u32, pub x: f64, pub y: f64, pub prev: usize, pub next: usize, pub removed: bool }
pub struct Ll { pub v: Vec<Node> }
impl Ll {
    fn insert(&mut self, i: u32, p: Pt, last: Option<usize>) -> usize {
        let h = self.v.len();
        self.v.push(Node { i, x: p[0], y: p[1], prev: h, next: h, removed: false });
        match last { None => {}, Some(l) => { let ln = self.v[l].next; self.v[h].next = ln; self.v[h].prev = l; self.v[ln].prev = h; self.v[l].next = h; } }
        h
    }
    fn remove(&mut self, n: usize) { let (p, nx) = (self.v[n].prev, self.v[n].next); self.v[p].next = nx; self.v[nx].prev = p; self.v[n].removed = true; }
}
fn area(p: &Node, q: &Node, r: &Node) -> f64 { (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y) }
fn point_in_triangle(ax:f64,ay:f64,bx:f64,by:f64,cx:f64,cy:f64,px:f64,py:f64)->bool{
    (cx-px)*(ay-py)-(ax-px)*(cy-py) >= 0.0 && (ax-px)*(by-py)-(bx-px)*(ay-py) >= 0.0 && (bx-px)*(cy-py)-(cx-px)*(by-py) >= 0.0
}
fn is_ear(ll: &Ll, ear: usize) -> bool {
    let (a, b, c) = (&ll.v[ll.v[ear].prev], &ll.v[ear], &ll.v[ll.v[ear].next]);
    if area(a, b, c) >= 0.0 { return false; }
    let (ax,ay,bx,by,cx,cy)=(a.x,a.y,b.x,b.y,c.x,c.y);
    let (pa, nb) = (ll.v[ear].prev, ll.v[ear].next);
    let mut p = ll.v[nb].next;
    while p != pa {
        let n = &ll.v[p];
        if point_in_triangle(ax,ay,bx,by,cx,cy,n.x,n.y) && area(&ll.v[n.prev], n, &ll.v[n.next]) >= 0.0 { return false; }
        p = ll.v[p].next;
    }
    true
}
pub fn earcut(polygon: &[Vec<Pt>]) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    if polygon.is_empty() { return out; }
    let ring = &polygon[0];
    let mut ll = Ll { v: Vec::with_capacity(ring.len()) };
    if ring.is_empty() { return out; }
    let n = ring.len();
    let mut sum = 0.0f64;
    for i in 0..n { let j = if i == 0 { n - 1 } else { i - 1 }; sum += (ring[j][0] - ring[i][0]) * (ring[i][1] + ring[j][1]); }
    let mut last: Option<usize> = None;
    if sum > 0.0 { for i in 0..n { last = Some(ll.insert(i as u32, ring[i], last)); } }
    else { for i in (0..n).rev() { last = Some(ll.insert(i as u32, ring[i], last)); } }
    let mut l = last.unwrap();
    let ln = ll.v[l].next;
    if ll.v[l].x == ll.v[ln].x && ll.v[l].y == ll.v[ln].y { ll.remove(l); l = ln; }
    if ll.v[l].prev == ll.v[l].next { return out; }
    let mut ear = l;
    loop {
        if ll.v[ear].prev == ll.v[ear].next { break; }
        let stop_init = ear; let mut stop = stop_init;
        loop {
            if ll.v[ear].prev == ll.v[ear].next { return out; }
            if is_ear(&ll, ear) {
                let (p, nx) = (ll.v[ear].prev, ll.v[ear].next);
                out.push(ll.v[p].i); out.push(ll.v[ear].i); out.push(ll.v[nx].i);
                ll.remove(ear);
                ear = ll.v[nx].next; stop = ll.v[nx].next;
                break;
            }
            ear = ll.v[ear].next;
            if ear == stop { return out; }
        }
        let _ = stop;
    }
    out
}
